// Usage: node styles.mjs '<json array of [label, selector]>' -> prints computed styles + rect for first match.
import { connect } from "./cdp.mjs";
import { readFileSync } from "node:fs";
const run = JSON.parse(readFileSync("C:/Users/chris/AppData/Local/Temp/agents/resurf/qa/run.json", "utf8"));
const items = JSON.parse(process.argv[2]);
const c = await connect(run.port);
const rows = await c.evaluateFn((items) => {
  const props = ["font-family", "font-size", "font-weight", "line-height", "letter-spacing", "color", "background-color", "background-image", "border-top-left-radius", "border-top-width", "border-top-color", "padding-left", "padding-right", "padding-top", "gap", "backdrop-filter", "box-shadow", "text-transform", "opacity"];
  return items.map(([label, sel]) => {
    const el = document.querySelector(sel);
    if (!el) return { label, sel, missing: true };
    const cs = getComputedStyle(el);
    const r = el.getBoundingClientRect();
    const out = { label, sel, rect: [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)] };
    for (const p of props) {
      const v = cs.getPropertyValue(p);
      if (v && v !== "none" && v !== "normal" && v !== "0px" && v !== "start" && v !== "auto") out[p] = v.length > 140 ? v.slice(0, 140) + "…" : v;
    }
    return out;
  });
}, items);
for (const row of rows) console.log(JSON.stringify(row));
c.close();
process.exit(0);
EOF
