// Computed-style probe shared by the QA driver. items: [[label, selector], ...]; "text:<s>" matches by direct text.
export async function probe(c, items) {
  return c.evaluateFn((items) => {
    const props = ["font-family", "font-size", "font-weight", "line-height", "letter-spacing", "color", "background-color", "background-image", "border-top-left-radius", "border-top-width", "border-top-color", "padding-top", "padding-right", "padding-bottom", "padding-left", "gap", "backdrop-filter", "box-shadow", "text-transform", "opacity"];
    const find = (sel) => {
      if (sel.startsWith("text:")) {
        const s = sel.slice(5);
        return [...document.querySelectorAll("body *")].find((el) => [...el.childNodes].some((n) => n.nodeType === 3 && n.textContent.includes(s)) && !el.closest("script"));
      }
      return document.querySelector(sel);
    };
    return items.map(([label, sel]) => {
      const el = find(sel);
      if (!el) return { label, sel, missing: true };
      const cs = getComputedStyle(el);
      const r = el.getBoundingClientRect();
      const out = { label, rect: [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)] };
      for (const p of props) {
        const v = cs.getPropertyValue(p);
        if (v && v !== "none" && v !== "normal" && v !== "0px" && v !== "start" && v !== "auto" && v !== "rgba(0, 0, 0, 0)") out[p] = v.length > 120 ? v.slice(0, 120) + "..." : v;
      }
      return out;
    });
  }, items);
}
export const printRows = (rows) => { for (const r of rows) console.log(JSON.stringify(r)); };
