const has = (sel) => c.evaluate(`Boolean(document.querySelector(${q(sel)}))`);
const insertText = (text) => c.send("Input.insertText", { text });
const key = async (k, code, vk, text) => {
  const base = { key: k, code, windowsVirtualKeyCode: vk };
  await c.send("Input.dispatchKeyEvent", { type: text ? "keyDown" : "rawKeyDown", ...base, ...(text ? { text } : {}) });
  await c.send("Input.dispatchKeyEvent", { type: "keyUp", ...base });
};
const escape = () => key("Escape", "Escape", 27);
const blur = () => c.evaluate("document.activeElement && document.activeElement.blur(), true");
const cropShot = async (file, selector, pad = 14) => {
  const rect = await c.evaluate(`(()=>{const el=document.querySelector(${q(selector)}); if(!el) return null; const r=el.getBoundingClientRect(); return {x:r.x,y:r.y,width:r.width,height:r.height};})()`);
  if (!rect) throw new Error("crop target missing " + selector);
  const clip = { x: Math.max(0, rect.x - pad), y: Math.max(0, rect.y - pad), width: rect.width + pad * 2, height: rect.height + pad * 2, scale: 1 };
  const { data } = await c.send("Page.captureScreenshot", { format: "png", clip });
  writeFileSync(file, Buffer.from(data, "base64"));
};
