$qa = "C:\Users\chris\AppData\Local\Temp\agents\resurf\qa"
$chat = "C:\Users\chris\AppData\Local\Temp\agents\chat-images\resurf-redesign"
Add-Type -AssemblyName System.Drawing
$frames = [ordered]@{
  "rest (sidebar mark)" = "mascot-rest.png";
  "t0 click" = "mascot-t0.png";
  "t1 +120ms" = "mascot-t1.png";
  "t2 +250ms" = "mascot-t2.png";
  "t3 settled" = "mascot-t3.png";
  "listening" = "mascot-listening.png";
  "reading" = "mascot-reading2.png";
  "no matches" = "mascot-nomatch.png";
  "back home (esc)" = "mascot-backhome.png";
}
$imgs = @()
foreach ($k in $frames.Keys) { $imgs += [pscustomobject]@{ label = $k; img = [System.Drawing.Image]::FromFile((Join-Path $qa $frames[$k])) } }
$labelW = 170; $pad = 14; $gap = 14
$contentW = ($imgs | ForEach-Object { $_.img.Width } | Measure-Object -Maximum).Maximum
$totalH = $pad; foreach ($i in $imgs) { $totalH += $i.img.Height + $gap }
$totalH += $pad
$W = $labelW + $contentW + $pad * 2
$bmp = New-Object System.Drawing.Bitmap $W, $totalH
$g = [System.Drawing.Graphics]::FromImage($bmp)
$g.Clear([System.Drawing.Color]::FromArgb(12,12,11))
$g.SmoothingMode = "AntiAlias"; $g.TextRenderingHint = "AntiAliasGridFit"
$font = New-Object System.Drawing.Font "Consolas", 10
$brush = New-Object System.Drawing.SolidBrush ([System.Drawing.Color]::FromArgb(141,134,124))
$y = $pad
foreach ($i in $imgs) {
  $g.DrawString($i.label, $font, $brush, $pad, $y + 4)
  $g.DrawImage($i.img, $labelW + $pad, $y, $i.img.Width, $i.img.Height)
  $y += $i.img.Height + $gap
}
$out = Join-Path $chat "qa-4-1-mascot-app.png"
$bmp.Save($out, [System.Drawing.Imaging.ImageFormat]::Png)
foreach ($i in $imgs) { $i.img.Dispose() }
$g.Dispose(); $bmp.Dispose()
"composite: $W x $totalH -> $out"
if (Test-Path (Join-Path $chat "qa-4-1-mascot-app.png")) { "ok" }

