// Drives the preview app through the Paper artboard states and saves app screenshots + style probes.
import { connect } from "./cdp.mjs";
import { probe } from "./probe.mjs";
import { readFileSync, writeFileSync, appendFileSync, rmSync } from "node:fs";
const QA = "C:/Users/chris/AppData/Local/Temp/agents/resurf/qa";
const OUT = "C:/Users/chris/AppData/Local/Temp/agents/chat-images/resurf-redesign";
const run = JSON.parse(readFileSync(`${QA}/run.json`, "utf8"));
const probesFile = `${QA}/probes2.jsonl`;
rmSync(probesFile, { force: true });
const c = await connect(run.port);
const q = (s) => JSON.stringify(s);
const clickSel = (sel) => c.evaluate(`(()=>{const el=document.querySelector(${q(sel)}); if(!el) return false; el.click(); return true;})()`);
const clickText = (sel, text) => c.evaluate(`(()=>{const el=[...document.querySelectorAll(${q(sel)})].find(n=>n.textContent.trim().startsWith(${q(text)})); if(!el) return false; el.click(); return true;})()`);
const has = (sel) => c.evaluate(`Boolean(document.querySelector(${q(sel)}))`);
const insertText = (text) => c.send("Input.insertText", { text });
const key = async (k, code, vk, text) => {
  const base = { key: k, code, windowsVirtualKeyCode: vk };
  await c.send("Input.dispatchKeyEvent", { type: text ? "keyDown" : "rawKeyDown", ...base, ...(text ? { text } : {}) });
  await c.send("Input.dispatchKeyEvent", { type: "keyUp", ...base });
};
const escape = () => key("Escape", "Escape", 27);
const blur = () => c.evaluate("document.activeElement && document.activeElement.blur(), true");
const cropShot = async (file, selector, pad = 14) => {
  const rect = await c.evaluate(`(()=>{const el=document.querySelector(${q(selector)}); if(!el) return null; const r=el.getBoundingClientRect(); return {x:r.x,y:r.y,width:r.width,height:r.height};})()`);
  if (!rect) throw new Error("crop target missing " + selector);
  const clip = { x: Math.max(0, rect.x - pad), y: Math.max(0, rect.y - pad), width: rect.width + pad * 2, height: rect.height + pad * 2, scale: 1 };
  const { data } = await c.send("Page.captureScreenshot", { format: "png", clip });
  writeFileSync(file, Buffer.from(data, "base64"));
};
const results = [];
const step = async (name, fn) => {
  try {
    await fn();
    results.push(`PASS ${name}`);
  } catch (e) {
    results.push(`FAIL ${name}: ${e.message}`);
  }
  console.log(results.at(-1));
};
const record = async (artboard, items) => {
  const rows = await probe(c, items);
  appendFileSync(probesFile, JSON.stringify({ artboard, rows }) + "\n");
};

// Start from a clean sample state.
await c.send("Page.reload", { ignoreCache: true });
await c.sleep(1200);
await c.waitFor('document.querySelector(".library-card")', 20000);
await c.sleep(1000);

await step("1.1 library shot", async () => {
  await c.shot(`${OUT}/qa-1-1-library-app.png`);
  await record("1.1", [["sidebar", "aside.sidebar"], ["brand-mark", "div.brand-mark"], ["nav-active", "button.nav-item.active"], ["nav-label-active", "button.nav-item.active .nav-label"], ["nav-count", "button.nav-item.active .nav-count"], ["nav-item2", "button.nav-item:nth-of-type(2)"], ["spaces-heading", "div.sidebar-heading span"], ["space-item", "div.space-item"], ["space-name", "span.space-name"], ["settings", "button.footer-item"], ["main", "main.main-content"], ["capture-bar", "section.capture-bar"], ["history-nav", "div.history-nav"], ["view-controls", "fieldset.view-controls"], ["search-field", "label.search-field"], ["search-rest", "span.search-rest"], ["add-button", "button.add-button"], ["library-grid", "div.library-grid"], ["card-slot", "div.library-card-slot"], ["card-first", "article.library-card"], ["note-card", "article.note-card"], ["note-title", "text:Books to reread"], ["note-label", "text:NOTE"], ["edge-tab", "button.edge-tab"]]);
});

await step("1.2 click search pill", async () => {
  if (!(await clickSel("label.search-field"))) throw new Error("no search pill");
  await c.waitFor('document.activeElement === document.querySelector(\'input[aria-label="Search your mind"]\')', 5000);
  await c.sleep(900);
  await cropShot(`${QA}/mascot-listening.png`, "label.search-field");
  await c.shot(`${OUT}/qa-1-2-search-drops-in-app.png`);
  await record("1.2", [["search-field", "label.search-field"], ["input", 'input[aria-label="Search your mind"]'], ["mascot-eyes", "label.search-field .field-mascot svg"], ["kbd", "label.search-field kbd"]]);
});

await step("1.3 type query, blur to pin", async () => {
  await insertText("lanterns");
  await c.sleep(600);
  await cropShot(`${QA}/mascot-reading.png`, "label.search-field");
  await blur();
  await c.waitFor('Boolean(document.querySelector(".query-chip-text"))', 8000);
  await c.sleep(1000);
  await c.shot(`${OUT}/qa-1-3-query-pinned-app.png`);
  await record("1.3", [["chip", ".query-chip-text"], ["search-field", "label.search-field"], ["grid-first", "article.library-card"]]);
});

await step("2.1 open image card", async () => {
  const ok = await c.evaluate(`(()=>{const cards=[...document.querySelectorAll("article.library-card")]; const img = cards.find(a=>(a.textContent||"").includes("Lanterns")) ?? cards.find(a=>a.querySelector("img")); if(!img) return false; img.click(); return true;})()`);
  if (!ok) throw new Error("no image card");
  await c.waitFor('document.querySelector(".expanded-overlay")', 8000);
  await c.sleep(1100);
  await c.shot(`${OUT}/qa-2-1-item-inspector-app.png`);
  await record("2.1", [["overlay", ".expanded-overlay"], ["tabs", ".item-inspector-tabs"], ["tab", ".item-inspector-tab"], ["zoom-pill", ".item-zoom-pill"], ["zoom-label", ".item-zoom-label"], ["close", 'button[aria-label="Close details"]'], ["archive", 'button[aria-label="Archive"]']]);
});

await step("2.2 similar tab", async () => {
  if (!(await clickText(".item-inspector-tab", "Similar"))) throw new Error("no Similar tab");
  await c.sleep(1400);
  await c.shot(`${OUT}/qa-2-2-similar-tab-app.png`);
  await record("2.2", [["tabs", ".item-inspector-tabs"], ["tab", ".item-inspector-tab"]]);
});

await step("2.3 zoom past 800 percent", async () => {
  await clickText(".item-inspector-tab", "Info");
  await c.sleep(300);
  for (let i = 0; i < 24; i++) {
    const label = await c.evaluate('document.querySelector(".item-zoom-label")?.textContent ?? ""');
    if (parseInt(label, 10) >= 1600) break;
    await clickSel('button[aria-label="Zoom in"]');
    await c.sleep(130);
  }
  await c.sleep(900);
  const zoomed = await c.evaluate('document.querySelector(".item-zoom-label")?.textContent ?? ""');
  await c.shot(`${OUT}/qa-2-3-zoomed-in-app.png`);
  await record("2.3", [["zoom-label", ".item-zoom-label"], ["zoom-pill", ".item-zoom-pill"], ["zoom-in", 'button[aria-label="Zoom in"]']]);
  results.push(`INFO zoom label at shot: ${zoomed}`);
});

await step("archive the open item", async () => {
  // Reset zoom so the archive button and the inspector are back to their normal layout.
  for (let i = 0; i < 24; i++) {
    const label = await c.evaluate('document.querySelector(".item-zoom-label")?.textContent ?? ""');
    if (!label || parseInt(label, 10) <= 80) break;
    await clickSel('button[aria-label="Zoom out"]');
    await c.sleep(120);
  }
  await clickText(".item-inspector-tab", "Info");
  await c.sleep(400);
  if (!(await clickSel('button[aria-label="Archive"]'))) throw new Error("no archive button");
  await c.sleep(7000);
  await c.evaluate(`(()=>{const b=document.querySelector("[data-sonner-toast] [data-close-button]"); if(b){b.click();} return Boolean(b);})()`);
  await c.sleep(900);
});

await step("close overlay if open", async () => {
  if (await has(".expanded-overlay")) {
    if (!(await clickSel('button[aria-label="Close details"]'))) await escape();
    await c.waitFor('!document.querySelector(".expanded-overlay")', 5000);
  }
  await c.sleep(500);
});

await step("3.1 settings library", async () => {
  if (!(await clickSel('button[aria-label="Settings"]'))) throw new Error("no settings button");
  await c.waitFor('Boolean(document.querySelector(\'aside[aria-label="Settings sections"]\'))', 6000);
  await c.sleep(900);
  await c.shot(`${OUT}/qa-3-1-settings-library-app.png`);
  await record("3.1", [["settings-sidebar", 'aside[aria-label="Settings sections"]'], ["settings-tab-active", ".settings-tab.active"], ["settings-tab", ".settings-tab"]]);
});

await step("3.2 settings archive", async () => {
  if (!(await clickText(".settings-tab", "Archive"))) throw new Error("no Archive tab");
  await c.waitFor('Boolean(document.querySelector(\'.settings-tab.active[aria-current="page"]\'))', 6000);
  await c.sleep(900);
  await c.shot(`${OUT}/qa-3-2-settings-archive-app.png`);
  await record("3.2", [["settings-tab-active", ".settings-tab.active"], ["settings-sidebar", 'aside[aria-label="Settings sections"]']]);
});

await step("close settings", async () => {
  await escape();
  await c.waitFor('!document.querySelector(\'aside[aria-label="Settings sections"]\')', 6000);
  await c.sleep(600);
});

// Mascot strip: reload for a clean sample state, then walk the search-bar states.
await step("4.1 mascot frames", async () => {
  await c.send("Page.reload", { ignoreCache: true });
  await c.sleep(1200);
  await c.waitFor('document.querySelector(".library-card")', 20000);
  await c.sleep(800);
  await cropShot(`${QA}/mascot-rest.png`, "div.brand-mark", 8);
  await clickSel("label.search-field");
  await cropShot(`${QA}/mascot-t0.png`, "label.search-field", 10);
  await c.sleep(120);
  await cropShot(`${QA}/mascot-t1.png`, "label.search-field", 10);
  await c.sleep(130);
  await cropShot(`${QA}/mascot-t2.png`, "label.search-field", 10);
  await c.sleep(300);
  await cropShot(`${QA}/mascot-t3.png`, "label.search-field", 10);
  await c.sleep(300);
  await insertText("lanterns");
  await c.sleep(500);
  await cropShot(`${QA}/mascot-reading2.png`, "label.search-field", 10);
  await c.evaluate(`(()=>{const i=document.querySelector('input[aria-label="Search your mind"]'); if(i){i.select();} return true;})()`);
  await insertText("purple giraffe tuesday");
  await c.sleep(800);
  await cropShot(`${QA}/mascot-nomatch.png`, "label.search-field", 10);
  await c.shot(`${OUT}/qa-4-1-mascot-app.png`);
  await escape();
  await c.sleep(420);
  await cropShot(`${QA}/mascot-backhome.png`, "label.search-field", 10);
  await c.sleep(600);
});

results.push(`CONSOLE ERRORS: ${c.consoleErrors.length}`);
for (const e of c.consoleErrors.slice(0, 8)) results.push(`  ${e.slice(0, 200)}`);
writeFileSync(`${QA}/drive2.log`, results.join("\n") + "\n");
console.log(results.join("\n"));
c.close();
process.exit(0);

