// Verifies three 1.2/1.3 questions against the running preview app: the focus outline source on the expanded search bar, the pinned chip container rect versus the first card, and the first card top.
import { connect } from "./cdp.mjs";
import { readFileSync } from "node:fs";
const QA = "C:/Users/chris/AppData/Local/Temp/agents/resurf/qa";
const run = JSON.parse(readFileSync(`${QA}/run.json`, "utf8"));
const c = await connect(run.port);
const out = {};

await c.send("Page.reload", { ignoreCache: true });
await c.sleep(1200);
await c.waitFor('document.querySelector(".library-card")', 20000);
await c.sleep(800);

// 1.2: expanded search bar, focused.
await c.evaluate(`(()=>{const el=document.querySelector("label.search-field"); if(!el) return false; el.click(); return true;})()`);
await c.waitFor('document.activeElement === document.querySelector(\'input[aria-label="Search your mind"]\')', 5000);
await c.sleep(900);
out.focused = await c.evaluate(`(()=>{
  const bar=document.querySelector("label.search-field");
  const input=document.querySelector('input[aria-label="Search your mind"]');
  const s=getComputedStyle(bar), i=getComputedStyle(input);
  return {
    barFocusWithin: bar.matches(":focus-within"),
    inputFocusVisible: input.matches(":focus-visible"),
    barOutline: s.outlineStyle + " " + s.outlineWidth + " " + s.outlineColor,
    barBoxShadow: s.boxShadow,
    barBorderTop: s.borderTopColor,
    inputOutline: i.outlineStyle + " " + i.outlineWidth + " " + i.outlineColor,
