// Second pass: open an image card, read the inspector section styles, switch to Similar, and list the top-right controls that sit near the Close button.
import { connect } from "./cdp.mjs";
import { readFileSync } from "node:fs";
const QA = "C:/Users/chris/AppData/Local/Temp/agents/resurf/qa";
const run = JSON.parse(readFileSync(`${QA}/run.json`, "utf8"));
const c = await connect(run.port);
const q = (s) => JSON.stringify(s);
const probeSel = (sel) => `(()=>{const els=[...document.querySelectorAll(${q(sel)})].slice(0,3); return els.map(el=>{const r=el.getBoundingClientRect(); const s=getComputedStyle(el); return {rect:[Math.round(r.x),Math.round(r.y),Math.round(r.width),Math.round(r.height)], text:(el.textContent||"").trim().slice(0,32), fontSize:s.fontSize, fontWeight:s.fontWeight, lineHeight:s.lineHeight, letterSpacing:s.letterSpacing, textTransform:s.textTransform, color:s.color, bg:s.backgroundColor, radius:s.borderRadius, borderTop:s.borderTopWidth+" "+s.borderTopColor, gap:s.gap, padding:s.paddingTop+" "+s.paddingRight+" "+s.paddingBottom+" "+s.paddingLeft};});})()`;
const out = {};

await c.send("Page.reload", { ignoreCache: true });
await c.sleep(1200);
await c.waitFor('document.querySelector(".library-card")', 20000);
await c.sleep(800);

const opened = await c.evaluate(`(()=>{const cards=[...document.querySelectorAll("article.library-card")]; const img=cards.find(a=>(a.textContent||"").includes("Lantern")) ?? cards.find(a=>a.querySelector("img")); if(!img) return false; img.click(); return true;})()`);
out.opened = opened;
await c.waitFor('document.querySelector(".expanded-overlay")', 8000);
await c.sleep(1100);

out.inspector = {
  tabs: await c.evaluate(probeSel(".item-inspector-tab")),
  title: await c.evaluate(probeSel("h2.item-title")),
  note: await c.evaluate(probeSel("p.item-note")),
  swatches: await c.evaluate(probeSel(".item-swatch")),
  spaceChip: await c.evaluate(probeSel(".item-space-chip")),
  details: await c.evaluate(probeSel("section.item-details")),
  detailRows: await c.evaluate(probeSel("section.item-details > div")),
  actionBar: await c.evaluate(probeSel(".item-action-bar")),
  actions: await c.evaluate(probeSel(".item-actions")),
  zoomPill: await c.evaluate(probeSel(".item-zoom-pill")),
};

// Top-right controls in the overlay state, to see what overlaps the Close button.
out.topRightOpen = await c.evaluate(`(()=>{return [...document.querySelectorAll("button, [role=button], a")].filter(b=>{const r=b.getBoundingClientRect(); return r.width>0 && r.y<60 && r.x>1100;}).map(b=>{const r=b.getBoundingClientRect(); return {label:b.getAttribute("aria-label")||b.title||(b.textContent||"").trim().slice(0,20), rect:[Math.round(r.x),Math.round(r.y),Math.round(r.width),Math.round(r.height)], position:getComputedStyle(b).position, zIndex:getComputedStyle(b).zIndex};});})()`);
out.windowControlsParent = await c.evaluate(`(()=>{const btn=[...document.querySelectorAll("button")].find(b=>/minimi|maximi|close window|restore/i.test(b.getAttribute("aria-label")||b.title||"")); if(!btn) return null; let el=btn; const chain=[]; for(let k=0;k<3&&el;k++){ const s=getComputedStyle(el); chain.push({tag:el.tagName.toLowerCase(), cls:String(el.className).slice(0,60), position:s.position, top:s.top, right:s.right, zIndex:s.zIndex}); el=el.parentElement;} return chain;})()`);

// Similar tab.
const clicked = await c.evaluate(`(()=>{const el=[...document.querySelectorAll(".item-inspector-tab")].find(n=>n.textContent.trim().startsWith("Similar")); if(!el) return false; el.click(); return true;})()`);
out.clickedSimilar = clicked;
await c.sleep(1400);
out.similar = {
  tabs: await c.evaluate(probeSel(".item-inspector-tab")),
  empty: await c.evaluate(probeSel(".item-similar-empty")),
  similar: await c.evaluate(probeSel(".item-similar")),
};

console.log(JSON.stringify(out, null, 1));
c.close();
process.exit(0);

