$root = 40876
$rootProc = Get-CimInstance Win32_Process -Filter "ProcessId=$root" -ErrorAction SilentlyContinue
if ($null -eq $rootProc -or $rootProc.CommandLine -notlike '*inkling-resurf-qa-TtTTN2*') {
  'root identity check failed or process gone; not stopping anything'
} else {
  $all = Get-CimInstance Win32_Process
  $ids = New-Object System.Collections.Generic.List[int]
  $queue = New-Object System.Collections.Generic.Queue[int]
  $queue.Enqueue($root)
  while ($queue.Count -gt 0) {
    $cur = $queue.Dequeue()
    foreach ($p in $all) {
      if ($p.ParentProcessId -eq $cur -and -not $ids.Contains([int]$p.ProcessId)) {
        $ids.Add([int]$p.ProcessId); $queue.Enqueue([int]$p.ProcessId)
      }
    }
  }
  "descendants of $root : $($ids -join ', ')"
  foreach ($id in $ids) { Stop-Process -Id $id -Force -ErrorAction SilentlyContinue }
  Stop-Process -Id $root -Force -ErrorAction SilentlyContinue
}
$left = Get-Process -Id 40876 -ErrorAction SilentlyContinue
if ($null -eq $left) { 'PID 40876 is gone' } else { "PID 40876 still running: $($left.ProcessName)" }

